PIs(\"inspect.sourceId\").setValue(parseFloat(inspectInitData.sourceId));\n\t}\n\t//来源表单id\n\tif(inspectInitData.sourceTableId !== undefined){\n\t\tReactAPI.getComponentAPI(\"InputNumber\").APIs(\"inspect.sourceTableId\").setValue(parseFloat(inspectInitData.sourceTableId));\n\t}\n\t//来源类型\n\tif(inspectInitData.sourceType !== undefined){\n\t\tReactAPI.getComponentAPI(\"SystemCode\").APIs(\"inspect.sourceType\").setValue(inspectInitData.sourceType);\n\t}\n\t//来源单据编号\n\tif(inspectInitData.sourcTableNo !== undefined){\n\t\tReactAPI.getComponentAPI(\"Input\").APIs(\"inspect.sourcTableNo\").setValue(inspectInitData.sourcTableNo);\n\t}\n\t//请检人\n\tif(inspectInitData.applyStaffId !== undefined){\n\t\tReactAPI.getComponentAPI(\"Reference\").APIs(\"inspect.applyStaffId.name\").setValue(inspectInitData.applyStaffId);\n\t}\n\t//请检部门\n\tif(inspectInitData.applyDeptId !== undefined){\n\t\tReactAPI.getComponentAPI(\"Reference\").APIs(\"inspect.applyDeptId.name\").setValue(inspectInitData.applyDeptId);\n\t}\n\t//请检时间\n\tif(inspectInitData.applyTime !== undefined){\n\t\tReactAPI.getComponentAPI(\"DatePicker\").APIs(\"inspect.applyTime\").setValue(new Date(inspectInitData.applyTime));\t\n\t}\n\t//业务类型\n\tif(inspectInitData.busiType !== undefined){\n\t\tReactAPI.getComponentAPI(\"Reference\").APIs(\"inspect.busiTypeId.name\").setValue(inspectInitData.busiType);\n\t}\n\t//备注\n\tif(inspectInitData.memo !== undefined){\n\t\tReactAPI.getComponentAPI(\"TextArea\").APIs(\"inspect.memoField\").setValue(inspectInitData.memo);\n\t}\n\n\t//批号\n\tif(inspectInitData.batchCode !== undefined){\n\t\tsetTimeout(function (){\n\t\t\tReactAPI.getComponentAPI(\"Input\").APIs(\"inspect.batchCode\").setValue(inspectInitData.batchCode);\n\t\t},400);\n\t}\n\t//需实验室检验，不传取默认值\n\tif(inspectInitData.needLabCheck !== undefined){\n\t\tReactAPI.getComponentAPI(\"Checkbox\").APIs(\"inspect.needLab\").setValue(inspectInitData.needLabCheck);\n\t}\n\t//采样点\n\tif(inspectInitData.psId !== undefined){\n\t\tReactAPI.getComponentAPI(\"Reference\").APIs(\"inspect.psId.name\").setValue(inspectInitData.psId);\n\t}\n\t//供应商\n\tif(inspectInitData.vendorId !== undefined){\n\t\tReactAPI.getComponentAPI(\"Reference\").APIs(\"inspect.vendorId.name\").setValue(inspectInitData.vendorId);\n\t}\n\t//物料ID\n\tif(inspectInitData.prodId !== undefined){\n\t\tReactAPI.getComponentAPI(\"Reference\").APIs(\"inspect.prodId.code\").setValue(inspectInitData.prodId);\n\t\tvar productObj = inspectInitData.prodId;\n\t\tsetTimeout(function (){\n\t\t\tproductObj.isBatch = {\n\t\t\t\tid:ReactAPI.getComponentAPI(\"SystemCode\").APIs(\"inspect.prodId.isBatch\").getValue().value\n\t\t\t}\n\t\t\tvar productArr = new Array();\n\t\t\tproductArr.push(productObj);\n\t\t\t//质量标准pt数据\n\t\t\tvar inspectStdDg = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"QCS_5.0.0.0_inspect_purchInspectEditdg1587627206280\");\n\t\t\t//检验项目PT数据\t\n\t\t\tvar inspectComDg = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"QCS_5.0.0.0_inspect_purchInspectEditdg1587627220062\");\n\t\t\tproductCodeSetCallBack(productArr, inspectStdDg, inspectComDg);\t\t\n\t\t},200);\n\t}\n}","isEasyTable":false,"firstTd":1,"officeNotNull":false,"copyColumn":false,"cellCode":"cell_1587627191245_9459","isTransCondition":false,"nodeExpanded":false,"importExcel":false,"isOfficeSign":false,"columnType":"DATAGRID","isTitle":true,"dataGridName":"dg1587627206280","hasFastQuery":false,"fields":[{"showTypeHasChanged":true,"precisionHasChanged":false,"onlyLeaf":false,"code":"QCS_5.0.0.0_inspect_purchInspectEditdg1587627206280_DATAGRID_OTHER_QCS_5.0.0.0_inspect_InspectStd_stdVerId_LIMSBasic_1.0.0_qualityStd_StdVersion_stdId_LIMSBasic_1.0.0_qualityStd_QualityStd_name","nullable":true,"isTotal":false,"showFormatHasChanged":true,"defaultValueHasChanged":false,"isCount":false,"dbColumnType":"TEXT","referenceview":{"code":"LIMSBasic_1.0.0_qualityStd_qualityStdVerRef","iscrosscompany":"false","name":"qualityStdVerRef","title":"LIMSBasic.viewtitle.randon1584520303249","mneType":