IT","rowspan":1,"cellCode":"cell_1587628968999_4243","name":"供应商","type":"layoutCell","element":{"couple":true,"onlyLeaf":false,"acceptRevisions":false,"iscontrol":false,"code":"QCS_5.0.0.0_inspect_purchInspectEdit_EDIT_LABEL_QCS_5.0.0.0_inspect_Inspect_vendorId_BaseSet_1.0.0_cooperate_Cooperate_name","nullable":true,"isOfficeHandSign":false,"multallowview":false,"isRevision":false,"hideRevision":false,"dbColumnType":"TEXT","getRevisions":false,"allowview":false,"propertyCode":"QCS_5.0.0.0_inspect_Inspect_vendorId||BaseSet_1.0.0_cooperate_Cooperate_name","readonly":false,"showRevision":false,"elalign":"right","convertPdfOnLine":true,"modelCode":"BaseSet_1.0.0_cooperate_Cooperate","complex":false,"namekey":"QCS.inspect.Inspect.vendorId","isreadonly":false,"showType":"LABEL","isgroup":false,"officePrint":false,"isCreateNew":false,"key":"inspect.vendorId.name","downloadDoc":true,"showFormat":"TEXT","officeNotNull":false,"autoresize":false,"mneenable":false,"isOfficeSign":false,"columnType":"TEXT","isTitle":true,"saveTemplate":false,"isrefselect":false,"name":"客商名称","isCustom":false,"refCondition":"return \"isSupplier=1\";","openEmptyDoc":true,"isNoCopy":false,"multable":false,"maxLength":255,"columnName":"NAME"}},{"callbackbody_es5":"function vendorIdRefCallback(objs) {\n\t//物料信息\n\tvar product = ReactAPI.getComponentAPI(\"Reference\").APIs(\"inspect.prodId.code\").getValue();\n\t//质量标准pt\n\tvar inspectStdDg = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"QCS_5.0.0.0_inspect_purchInspectEditdg1587627206280\");\n\tvar inspectStdDgData = inspectStdDg.getDatagridData();\n\tif (product.length > 0 && inspectStdDgData.length > 0) {\n\t\t//检验项目pt\n\t\tvar comDg = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"QCS_5.0.0.0_inspect_purchInspectEditdg1587627220062\");\n\t\t//给当前选中质量标准检验项目“检测频率”、“上次检测日期”等字段赋值\n\t\tvar comDgData = comDg.getDatagridData();\n\t\tif (comDgData.length > 0) {\n\t\t\tvar comNameStr = \"\";\n\t\t\tfor (var i = 0; i < comDgData.length; i++) {\n\t\t\t\tcomDgData[i].lastTestDate = null;\n\t\t\t\tcomDgData[i].testFrequency = null;\n\t\t\t\tcomDgData[i].countNum = null;\n\t\t\t\tcomNameStr += \"@##@\" + comDgData[i].stdVerComId.reportName;\n\t\t\t}\n\t\t\t//组织参数\n\t\t\tvar reqParam = {\n\t\t\t\tmaterialId: product[0].id,\n\t\t\t\ttestComponentNames: comNameStr,\n\t\t\t\tplanType: \"LIMSBasic_planType/rawMaterial\",\n\t\t\t\tmanufacturerId: objs[0].id\n\t\t\t};\n\t\t\t$.ajax({\n\t\t\t\turl: \"/msService/QCS/inspect/inspect/getTestPlanComs\",\n\t\t\t\ttype: \"post\",\n\t\t\t\tasync: false,\n\t\t\t\theaders: { ''Content-Type'': ''application/json;charset=utf8'' },\n\t\t\t\tdataType: \"json\",\n\t\t\t\tdata: JSON.stringify(reqParam), //物料id\n\t\t\t\tsuccess: function success(res) {\n\t\t\t\t\tvar testPlanComs = res.data;\n\t\t\t\t\tfor (var j = 0; j < comDgData.length; j++) {\n\t\t\t\t\t\tfor (var k = 0; k < testPlanComs.length; k++) {\n\t\t\t\t\t\t\tif (comDgData[j].stdVerComId.reportName === testPlanComs[k].testCom) {\n\t\t\t\t\t\t\t\tcomDgData[j].lastTestDate = testPlanComs[k].lastTestDate;\n\t\t\t\t\t\t\t\tcomDgData[j].testFrequency = testPlanComs[k].testFrequency;\n\t\t\t\t\t\t\t\tif (testPlanComs[k].countNum !== undefined && testPlanComs[k].countNum !== null) {\n\t\t\t\t\t\t\t\t\tcomDgData[j].countNum = testPlanComs[k].countNum + 1;\n\t\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\t\tbreak;\n\t\t\t\t\t\t\t}\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t\tcomDg.deleteLine();\n\t\t\t\t\tcomDg.addLine(comDgData);\n\t\t\t\t}\n\t\t\t});\n\t\t}\n\t\tconsole.log(inspectStdDgData);\n\t\t//给其他质量标准检验项目“检测频率”、“上次检测日期”等字段赋值\n\t\tfor (var i = 0; i < inspectStdDgData.length; i++) {\n\t\t\tvar stdComs = JSON.parse(inspectStdDgData[i].inspStdVerCom);\n\t\t\tif (stdComs.length > 0) {\n\t\t\t\tvar comNameStr = \"\";\n\t\t\t\tfor (var j = 0; j < stdComs.length; j++) {\n\t\t\t\t\tcomNameStr += \"@##@\" + stdComs[j].reportName;\n\t\t\t\t}\n\t\t\t\tcomNameStr = comNameStr.substring(4);\n\t\t\t\t//组织参数\n\t\t\t\tvar reqParam = {\n\t\t\t\t\tmaterialId: product[0].id,\n\t\t\t\t\ttestComponentNames: comNameStr,\n\t\t\t\t\tplanType: \"LIMSBasic_planType/rawMaterial\",\n\t\t\t\t\tmanufacturerId: objs[0].id\n\t\t\t\t};\n\t\t\t\t$.ajax({\n\t\t\t\t\turl: \"/msService/QCS/inspect/inspect/getTestPlanComs\",\n\t\t\t\t\ttype: \"post\",\n\t\t\t\t\tasync: false,\n\t\t\t\t\theaders: { ''Content-Type'': ''application/json;charset=utf8'' },\n\t\t\t\t\tdataType: \"json\",\n\t\t\t\t\tdata: JSON.stringify(reqParam), //物料id\n\t\t\t\t\tsuccess: function success(res) {\n\t\t\t\t\t\tvar testPlanComs = res.data;\n\t\t\t\t\t\tfor (var j = 0; j < stdComs.length; j++) {\n\t\t\t\t\t\t\tstdComs[j].lastTestDate = null;\n\t\t\t\t\t\t\tstdComs[j].testFrequency = null;\n\t\t\t\t\t\t\tstdComs[j].countNum = null;\n\t\t\t\t\t\t\tfor (var k = 0; k < testPlanComs.length; k++) {\n\t\t\t\t\t\t\t\tif (stdComs[j].reportName === testPlanComs[k].testCom) {\n\t\t\t\t\t\t\t\t\tstdComs[j].lastTestDate = testPlanComs[k].lastTestDate;\n\t\t\t\t\t\t\t\t\tstdComs[j].testFrequency = testPlanComs[k].testFrequency;\n\t\t\t\t\t\t\t\t\tif (testPlanComs[k].countNum !== undefined && testPlanComs[k].countNum !== null) {\n\t\t\t\t\t\t\t\t\t\tstdComs[j].countNum = testPlanComs[k].countNum + 1;\n\t\t\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\t\t\tbreak;\n\t\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\t}\n\t\t\t\t\t\t}\n\t\t\t\t\t\tinspectStdDg.setValueByKey(i, ''inspStdVerCom'', JSON.stringify(stdComs));\n\t\t\t\t\t}\n\t\t\t\t});\n\t\t\t}\n\t\t}\n\t\tconsole.log(inspectStdDg.getDatagridData());\n\t}\n}","callbackbody":"function vendorIdRefCallback(objs){\n\t//物料信息\n\tvar product = ReactAPI.getComponentAPI(\"Reference\").APIs(\"inspect.prodId.code\").getValue();\n\t//质量标准pt\n\tvar inspectStdDg = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"QCS_5.0.0.0_inspect_purchInspectEditdg1587627206280\");\n\tvar inspectStdDgData = inspectStdDg.getDatagridData();\n\tif(product.length > 0 && inspectStdDgData.length > 0){\n\t\t//检验项目pt\n\t\tvar comDg = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"QCS_5.0.0.0_inspect_purchInspectEditdg1587627220062\");\n\t\t//给当前选中质量标准检验项目“检测频率”、“上次检测日期”等字段赋值\n\t\tvar comDgData = comDg.getDatagridData();\n\t\tif(comDgData.length > 0){\n\t\t\tvar comNameStr = \"\";\n\t\t\tfor(var i = 0; i < comDgData.length; i++){\n\t\t\t\tcomDgData[i].lastTestDate = null;\n\t\t\t\tcomDgData[i].testFrequency = null;\n\t\t\t\tcomDgData[i].countNum = null;\n\t\t\t\tcomNameStr += \"@##@\" + comDgData[i].stdVerComId.reportName;\n\t\t\t}\n\t\t\t//组织参数\n\t\t\tvar reqParam = {\n\t\t\t\tmaterialId : product[0].id,\n\t\t\t\ttestComponentNames : comNameStr,\n\t\t\t\tplanType : \"LIMSBasic_planType/rawMaterial\",\n\t\t\t\tmanufacturerId : objs[0].id\n\t\t\t}\n\t\t\t$.ajax({\n\t\t\t\turl: \"/msService/QCS/inspect/inspect/getTestPlanComs\",\n\t\t\t\ttype: \"post\",\n\t\t\t\tasync: false,\n\t\t\t\theaders:{''Content-Type'':''application/json;charset=utf8''},\n\t\t\t\tdataType:\"json\",\n\t\t\t\tdata: JSON.stringify(reqParam),//物料id\n\t\t\t\tsuccess: function(res) {\n\t\t\t\t\tvar testPlanComs = res.data;\n\t\t\t\t\tfor(var j = 0; j < comDgData.length; j++){\n\t\t\t\t\t\tfor(var k = 0; k < testPlanComs.length; k++){\n\t\t\t\t\t\t\tif(comDgData[j].stdVerComId.reportName === testPlanComs[k].testCom){\n\t\t\t\t\t\t\t\tcomDgData[j].lastTestDate = testPlanComs[k].lastTestDate;\n\t\t\t\t\t\t\t\tcomDgData[j].testFrequency = testPlanComs[k].testFrequency;\n\t\t\t\t\t\t\t\tif(testPlanComs[k].countNum !== undefined && testPlanComs[k].countNum !== null){\n\t\t\t\t\t\t\t\t\tcomDgData[j].countNum = testPlanComs[k].countNum + 1;\n\t\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\t\tbreak;\n\t\t\t\t\t\t\t}\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t\tcomDg.deleteLine();\n\t\t\t\t\tcomDg.addLine(comDgData);\n\t\t\t\t}\n\t\t\t});\t\n\t\t}\n\t\tconsole.log(inspectStdDgData);\n\t\t//给其他质量标准检验项目“检测频率”、“上次检测日期”等字段赋值\n\t\tfor(var i = 0; i < inspectStdDgData.length; i++){\n\t\t\tvar stdComs = JSON.parse(inspectStdDgData[i].inspStdVerCom);\n\t\t\tif(stdComs.length > 0){\n\t\t\t\tvar comNameStr = \"\";\n\t\t\t\tfor(var j = 0; j < stdComs.length; j++){\n\t\t\t\t\tcomNameStr += \"@##@\" + stdComs[j].reportName;\n\t\t\t\t}\n\t\t\t\tcomNameStr = comNameStr.substring(4);\n\t\t\t\t//组织参数\n\t\t\t\tvar reqParam = {\n\t\t\t\t\tmaterialId : product[0].id,\n\t\t\t\t\ttestComponentNames : comNameStr,\n\t\t\t\t\tplanType : \"LIMSBasic_planType/rawMaterial\",\n\t\t\t\t\tmanufacturerId : objs[0].id\n\t\t\t\t}\n\t\t\t\t$.ajax({\n\t\t\t\t\turl: \"/msService/QCS/inspect/inspect/getTestPlanComs\",\n\t\t\t\t\ttype: \"post\",\n\t\t\t\t\tasync: false,\n\t\t\t\t\theaders:{''Content-Type'':''application/json;charset=utf8''},\n\t\t\t\t\tdataType:\"json\",\n\t\t\t\t\tdata: JSON.stringify(reqParam),//物料id\n\t\t\t\t\tsuccess: function(res) {\n\t\t\t\t\t\tvar testPlanComs = res.data;\n\t\t\t\t\t\tfor(var j = 0; j < stdComs.length; j++){\n\t\t\t\t\t\t\tstdComs[j].lastTestDate = null;\n\t\t\t\t\t\t\tstdComs[j].testFrequency = null;\n\t\t\t\t\t\t\tstdComs[j].countNum = null;\n\t\t\t\t\t\t\tfor(var k = 0; k < testPlanComs.length; k++){\n\t\t\t\t\t\t\t\tif(stdComs[j].reportName === testPlanComs[k].testCom){\n\t\t\t\t\t\t\t\t\tstdComs[j].lastTestDate = testPlanComs[k].lastTestDate;\n\t\t\t\t\t\t\t\t\tstdComs[j].testFrequency = testPlanComs[k].testFrequency;\n\t\t\t\t\t\t\t\t\tif(testPlanComs[k].countNum !== undefined && testPlanComs[k].countNum !== null){\n\t\t\t\t\t\t\t\t\t\tstdComs[j].countNum = testPlanComs[k].countNum + 1;\n\t\t\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\t\t\tbreak;\n\t\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\t}\n\t\t\t\t\t\t}\n\t\t\t\t\t\tinspectStdDg.setValueByKey(i, ''inspStdVerCom'', JSON.stringify(stdComs));\n\t\t\t\t\t}\n\t\t\t\t});\t\n\t\t\t}\n\t\t}\n\t\tconsole.log(inspectStdDg.getDatagridData());\n\t}\n}","funcbody":"function vendorIdAfterClear(){\n\t//质量标准pt\n\tvar inspectStdDg = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"QCS_5.0.0.0_inspect_purchInspectEditdg1587627206280\");\n\t//检验项目pt\n\tvar comDg = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"QCS_5.0.0.0_inspect_purchInspectEditdg1587627220062\");\n\t\