n\t\t\t\tsuccess: function success(res) {\n\t\t\t\t\tvar testPlanComs = res.data;\n\t\t\t\t\tfor (var j = 0; j < comDgData.length; j++) {\n\t\t\t\t\t\tfor (var k = 0; k < testPlanComs.length; k++) {\n\t\t\t\t\t\t\tif (comDgData[j].stdVerComId.reportName === testPlanComs[k].testCom) {\n\t\t\t\t\t\t\t\tcomDgData[j].lastTestDate = testPlanComs[k].lastTestDate;\n\t\t\t\t\t\t\t\tcomDgData[j].testFrequency = testPlanComs[k].testFrequency;\n\t\t\t\t\t\t\t\tif (testPlanComs[k].countNum !== undefined && testPlanComs[k].countNum !== null) {\n\t\t\t\t\t\t\t\t\tcomDgData[j].countNum = testPlanComs[k].countNum + 1;\n\t\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\t\tbreak;\n\t\t\t\t\t\t\t}\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t\tcomDg.deleteLine();\n\t\t\t\t\tcomDg.addLine(comDgData);\n\t\t\t\t}\n\t\t\t});\n\t\t}\n\t\tconsole.log(inspectStdDgData);\n\t\t//给其他质量标准检验项目“检测频率”、“上次检测日期”等字段赋值\n\t\tfor (var i = 0; i < inspectStdDgData.length; i++) {\n\t\t\tvar stdComs = JSON.parse(inspectStdDgData[i].inspStdVerCom);\n\t\t\tif (stdComs.length > 0) {\n\t\t\t\tvar comNameStr = \"\";\n\t\t\t\tfor (var j = 0; j < stdComs.length; j++) {\n\t\t\t\t\tcomNameStr += \"@##@\" + stdComs[j].reportName;\n\t\t\t\t}\n\t\t\t\tcomNameStr = comNameStr.substring(4);\n\t\t\t\t//组织参数\n\t\t\t\tvar reqParam = {\n\t\t\t\t\tmaterialId: product[0].id,\n\t\t\t\t\ttestComponentNames: comNameStr,\n\t\t\t\t\tplanType: \"LIMSBasic_planType/rawMaterial\",\n\t\t\t\t\tmanufacturerId: objs[0].id\n\t\t\t\t};\n\t\t\t\t$.ajax({\n\t\t\t\t\turl: \"/msService/QCS/inspect/inspect/getTestPlanComs\",\n\t\t\t\t\ttype: \"post\",\n\t\t\t\t\tasync: false,\n\t\t\t\t\theaders: { ''Content-Type'': ''application/json;charset=utf8'' },\n\t\t\t\t\tdataType: \"json\",\n\t\t\t\t\tdata: JSON.stringify(reqParam), //物料id\n\t\t\t\t\tsuccess: function success(res) {\n\t\t\t\t\t\tvar testPlanComs = res.data;\n\t\t\t\t\t\tfor (var j = 0; j < stdComs.length; j++) {\n\t\t\t\t\t\t\tstdComs[j].lastTestDate = null;\n\t\t\t\t\t\t\tstdComs[j].testFrequency = null;\n\t\t\t\t\t\t\tstdComs[j].countNum = null;\n\t\t\t\t\t\t\tfor (var k = 0; k < testPlanComs.length; k++) {\n\t\t\t\t\t\t\t\tif (stdComs[j].reportName === testPlanComs[k].testCom) {\n\t\t\t\t\t\t\t\t\tstdComs[j].lastTestDate = testPlanComs[k].lastTestDate;\n\t\t\t\t\t\t\t\t\tstdComs[j].testFrequency = testPlanComs[k].testFrequency;\n\t\t\t\t\t\t\t\t\tif (testPlanComs[k].countNum !== undefined && testPlanComs[k].countNum !== null) {\n\t\t\t\t\t\t\t\t\t\tstdComs[j].countNum = testPlanComs[k].countNum + 1;\n\t\t\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\t\t\tbreak;\n\t\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\t}\n\t\t\t\t\t\t}\n\t\t\t\t\t\tinspectStdDg.setValueByKey(i, ''inspStdVerCom'', JSON.stringify(stdComs));\n\t\t\t\t\t}\n\t\t\t\t});\n\t\t\t}\n\t\t}\n\t\tconsole.log(inspectStdDg.getDatagridData());\n\t}\n}","callbackname":"vendorIdRefCallback(objs)","element":{"couple":true,"onlyLeaf":false,"acceptRevisions":false,"iscontrol":false,"code":"QCS_5.0.0.0_inspect_purchInspectEdit_EDIT_OTHER_QCS_5.0.0.0_inspect_Inspect_vendorId_BaseSet_1.0.0_cooperate_Cooperate_name","nullable":true,"isOfficeHandSign":false,"multallowview":false,"isRevision":false,"hideRevision":false,"defaultValueHasChanged":false,"dbColumnType":"TEXT","referenceview":{"code":"BaseSet_1.0.0_cooperate_cmcLayoutRef","iscrosscompany":"false","name":"cmcLayoutRef","title":"BaseSet.viewtitle.randon1574075039260","mneType":"other","url":"/msService/BaseSet/cooperate/cooperate/cmcLayoutRef","openType":"frame"},"getRevisions":false,"allowview":false,"propertyCode":"QCS_5.0.0.0_inspect_Inspect_vendorId||BaseSet_1.0.0_cooperate_Cooperate_name","readonly":false,"showRevision":false,"elalign":"left","convertPdfOnLine":true,"modelCode":"BaseSet_1.0.0_cooperate_Cooperate","complex":false,"namekey":"QCS.inspect.Inspect.vendorId","isreadonly":false,"showType":"SELECTCOMP","isgroup":false,"officePrint":false,"isCreateNew":false,"key":"inspect.vendorId.name","downloadDoc":true,"showFormat":"SELECTCOMP","officeNotNull":false,"autoresize":false,"mneenable